const BASE='https://api.sleeper.app/v1';
export async function json(url){const r=await fetch(url,{signal:AbortSignal.timeout(22000)});if(!r.ok)throw Error(`Data service returned ${r.status}. Please try again.`);return r.json();}
export const sleeper=path=>json(BASE+path);
async function playerCache(write){try{return await new Promise(resolve=>{const req=indexedDB.open('sunday-cache',1);req.onupgradeneeded=()=>req.result.createObjectStore('data');req.onerror=()=>resolve(null);req.onsuccess=()=>{const db=req.result,tx=db.transaction('data',write?'readwrite':'readonly'),s=tx.objectStore('data'),r=write?s.put(write,'players'):s.get('players');r.onsuccess=()=>resolve(write||r.result);r.onerror=()=>resolve(null);tx.oncomplete=()=>db.close();};});}catch{return null;}}
export async function loadPlayers(){const cached=await playerCache();if(cached&&Date.now()-cached.time<86400000)return cached.data;const data=await sleeper('/players/nfl');await playerCache({time:Date.now(),data});return data;}
export async function discover(username){const user=await sleeper('/user/'+encodeURIComponent(username));if(!user?.user_id)throw Error('Sleeper username not found. Check the spelling and try again.');const nfl=await sleeper('/state/nfl');const leagues=await sleeper(`/user/${user.user_id}/leagues/nfl/${nfl.league_season||nfl.season}`);if(!leagues?.length)throw Error(`No NFL leagues found for ${username} in ${nfl.league_season||nfl.season}.`);return {user,nfl,leagues};}
export async function leagueDetails(l,userId,week){const [rosters,users,matchups]=await Promise.all([sleeper(`/league/${l.league_id}/rosters`),sleeper(`/league/${l.league_id}/users`),sleeper(`/league/${l.league_id}/matchups/${week}`)]);const mine=rosters.find(r=>r.owner_id===userId||(r.co_owners||[]).includes(userId));if(!mine)throw Error('No roster found for this user.');return {...l,rosters,users,matchups,mine,enabled:l.status!=='complete',syncedAt:Date.now()};}
const teamAlias=t=>({WSH:'WAS',WSN:'WAS',LA:'LAR',JAC:'JAX'}[t]||t);
export async function scoreboard(season,week){const d=await json(`https://site.api.espn.com/apis/site/v2/sports/football/nfl/scoreboard?dates=${season}&seasontype=2&week=${week}&limit=100`);const games={};for(const e of d.events||[]){const c=e.competitions?.[0];if(!c)continue;for(const team of c.competitors||[]){const other=c.competitors.find(x=>x.id!==team.id);games[teamAlias(team.team.abbreviation)]={id:e.id,state:e.status.type.state,detail:e.status.type.shortDetail,start:e.date,opponent:teamAlias(other?.team?.abbreviation),home:team.homeAway==='home',score:team.score,oppScore:other?.score,channel:c.broadcasts?.flatMap(b=>b.names||[]).join(' / ')||null};}}return games;}
export async function projections(season,week){const d=await json(`https://api.sleeper.app/projections/nfl/${season}/${week}?season_type=regular`);if(!Array.isArray(d))throw Error('Projection feed unavailable.');return Object.fromEntries(d.map(x=>[x.player_id,x]));}
export async function trends(){return sleeper('/players/nfl/trending/add?lookback_hours=24&limit=100');}
